registerRefData('nsw-cond-n-62',{"id":62,"pan":null,"ref":"DA24/0075","address":"185 Morgan Street Wagga Wagga 2650,72 Murray Street Wagga Wagga 2650,68 Murray Street Wagga Wagga 2650,70 Murray Street Wagga Wagga 2650,66 Murray Street Wagga Wagga 2650","description":"Mixed Use Development","outcome":"approved","outcome_raw":"Approved","outcome_source":"planning_panels","determined":"2026-05-05","notice_url":"https://apps.planningportal.nsw.gov.au/prweb/PRRestService/DocMgmt/v1/PublicDocuments/DATA-WORKATTACH-FILE PEC-DPE-EP-WORK PPSSTH-342!20260506T015617.025 GMT","sha256":"12a901a90ac2fec2fe9f129639c3280674ecab0461af68912d9ca89ceea92b9a","pages":32,"layout":"numbered","n":10,"fetched_at":"2026-08-16T23:19:06+00:00","file":"n/62.js","source_page":"https://www.planningportal.nsw.gov.au/planning-panel/mixed-use-development-261","lga":"WAGGA WAGGA","conditions":[{"label":"1","code":null,"number":"1","title":"","text":"PANEL REF - LGA - DA NO. PPSSTH-342 - WAGGA WAGGA - DA24/0075","stage":"general","stage_basis":"heading","page":4},{"label":"2","code":null,"number":"2","title":"","text":"PROPOSED DEVELOPMENT Mixed Use Development Including a 9 Storey Building, with Ground Floor\nCommercial Development, and 8 levels of Residential Apartments (Shop\nTop Housing), a 7 Storey Building, with Ground Floor Commercial\nDevelopment, and 6 levels of Residential\nApartments (Shop Top Housing), 8 x 3 Storey Attached Multi Dwelling\nHousing Dwellings, and Two Levels of Shared Basement Carparking.","stage":"general","stage_basis":"heading","page":4},{"label":"3","code":null,"number":"3","title":"","text":"STREET ADDRESS 185-187 and 66-72 Murray Street, Wagga Wagga NSW 2650 (Lot 1 DP\n550746, Lot 1 DP 203835 and Lots 1-4 DP 20847)","stage":"general","stage_basis":"heading","page":4},{"label":"4","code":null,"number":"4","title":"APPLICANT","text":"OWNER\nThe Trustee for The Donebus Family Trust\nDamasa Pty Ltd","stage":"general","stage_basis":"heading","page":4},{"label":"5","code":null,"number":"5","title":"TYPE OF REGIONAL","text":"DEVELOPMENT General development over $30 million","stage":"general","stage_basis":"heading","page":4},{"label":"6","code":null,"number":"6","title":"RELEVANT MANDATORY","text":"CONSIDERATIONS\n• Environmental planning instruments:\no State Environmental Planning Policy (Planning Systems) 2021\no State Environmental Planning Policy (Housing) 2021\no State Environmental Planning Policy (Transport and\nInfrastructure) 2021\no State Environmental Planning Policy (Sustainable Buildings) 2022\no Wagga Wagga Local Environmental Plan 2010\n• Draft environmental planning instruments: Nil\n• Development control plans:\no Wagga Wagga Development Control Plan 2010\n• Planning agreements: Nil\n• Relevant provisions of the Environmental Planning and Assessment\nRegulation 2021\n• Coastal zone management plan: Nil\n• The likely impacts of the development, including environmental\nimpacts on the natural and built environment and social and economic\nimpacts in the locality\n• The suitability of the site for the development\n• Any submissions made in accordance with the Environmental Planning\nand Assessment Act 1979 or regulations\n• The public interest, including the principles of ecologically sustainable\ndevelopment","stage":"general","stage_basis":"heading","page":4},{"label":"7","code":null,"number":"7","title":"MATERIAL CONSIDERED BY","text":"THE PANEL\n• Council Assessment Report: 15 April 2026\n• The Applicant’s response to the draft recommended conditions of\nconsent dated 17 April 2026\n• Council’s review of the draft recommended conditions of consent and\ncovering letter dated 24 April 2026\n• Written submissions during public exhibition: 2\n• Total number of unique submissions received by way of objection: 2","stage":"general","stage_basis":"heading","page":4},{"label":"8","code":null,"number":"8","title":"MEETINGS, BRIEFINGS AND","text":"SITE INSPECTIONS BY THE\nPANEL\n• Briefing: 26 March 2024\no Panel members: Chris Wilson (Chair), Grant Christmas, Amelia\nParkins, Michael Henderson\no Council assessment staff: Steven Cook, Kellie Stevens\no Applicant representatives: Manuel Donebus (The Trustee for The\nDonebus Family Trust), Daniel Donebus (The Trustee for The\nDonebus Family Trust), Glen Ollerton (Morrison Design\nPartnership), Amir Safaei (Morrison Design Partnership), Daniel\nTraficante (Morrison Design Partnership), Patrice McMullen\n(Salvestro Planning)\no DPHI: Amanda Moylan, Tracey Gillett, Lillian Charlesworth\n• Briefing: 24 July 2024\no Panel members: Chris Wilson (Chair), Juliet Grant, Grant\nChristmas, Amelia Parkins, Michael Henderson\no Council assessment staff: Steven Cook, Kellie Stevens, Scott\nButton (Council Consultant Flood Engineer)\no Applicant representatives: Manuel Donebus (The Trustee for The\nDonebus Family Trust), Daniel Donebus (The Trustee for The\nDonebus Family Trust), Glen Ollerton (Morrison Design\nPartnership), Amir Safaei (Morrison Design Partnership), Daniel\nTraficante (Morrison Design Partnership), Patrice McMullen\n(Salvestro Planning)\no DPHI: Amanda Moylan, Tracey Gillett\n• Site inspection: 23 July 2024\no Panel members: Grant Christmas, Amelia Parkins, Michael\nHenderson\no Council assessment staff: Steven Cook, Rebecca Fox\n• Site inspection: 8 August 2024\no Panel members: Chris Wilson (Chair), Juliet Grant\no Council assessment staff: Steven Cook\n• Final briefing to discuss council’s recommendation: 21 April 2026\no Panel members: Chris Wilson (Chair), Juliet Grant, Grant\nChristmas, Amelia Parkins, Jenny McKinnon\no Council assessment staff: Steven Cook, Amanda Gray, Alyssa\nCronk, Scott Button (Council Consultant Flood Engineer)\no Applicant representatives: Manuel Donebus (Director, The\nTrustee for The Donebus Family Trust), Daniel Donebus (Director,\nThe Trustee for The Donebus Family Trust), Glen Ollerton\n(Director, Morrison Design Partnership), Angela Wang (Associate,\nMorrison Design Partnership), David Hunter (Planner, Habitat\nPlanning), Patrice McMullen (Planner, Habitat Planning), Kathleen\nBolger (Associate, Habitat Planning), Angus Brien (Flood Engineer,\nNorthrop)\no DPHI: Riki Mey, Tracey Gillett","stage":"general","stage_basis":"heading","page":4},{"label":"9","code":null,"number":"9","title":"COUNCIL","text":"RECOMMENDATION Approval","stage":"general","stage_basis":"heading","page":5},{"label":"10","code":null,"number":"10","title":"DRAFT CONDITIONS Attached to the Council Assessment Report","text":"CONDITIONS OF CONSENT FOR APPLICATION NO. DA24/0075\nA. SCHEDULE A - Reasons for Conditions\nThe conditions of this consent have been imposed for the following reasons:\nA.1 To ensure compliance with the terms of the Environmental Planning and Assessment Act\n1979 and Regulation 2000.\nA.2 Having regard to Council's duties of consideration under Section 4.15 and 4.17 of the Act.\nA.3 To ensure an appropriate level of provision of amenities and services occurs within the City\nand to occupants of sites.\nA.4 To improve the amenity, safety and environmental quality of the locality.\nA.5 Having regard to environmental quality, the circumstances of the case and the public\ninterest.\nA.6 Having regard to the Wagga Wagga Development Control Plan 2010.\nA.7 To help retain and enhance streetscape quality.\nA.8 Ensure compatibility with adjoining and neighbouring land uses and built form.\nA.9 To protect public interest, the environment and existing amenity of the locality.\nA.10 To minimise health risk to neighbouring residents and workers.\nB. SCHEDULE B - Deferred Commencement Conditions\nN/A\nC. SCHEDULE C - Conditions\nApproved Plans and Documentation\nC.1 The development must be carried out in accordance with the approved plans and\nspecifications as follows.\nPlan/DocNo. Plan/Doc Title Prepared by Issue Date\nDA040 Existing/Demolition\nPlan\nMDP Architecture DA2 16/10/24\nDA050 Proposed Site Plan MDP Architecture DA2 16/10/24\nDA060 Proposed Site Ground\nPlan\nMDP Architecture DA2 16/10/24\nDA071 Stage 3 Construction\nStaging\nMDP Architecture DA1 02/04/26\nDA080 3D Rendered Views MDP Architecture DA2 16/10/24\nDA101 Basement 02 Floor Plan MDP Architecture DA2 16/10/24\nDA102 Basement 01 Floor Plan MDP Architecture DA2 16/10/24\nDA103 Ground Floor Plan MDP Architecture DA2 16/10/24\nDA104 Level 01 Floor Plan MDP Architecture DA2 16/10/24\nDA105 Level 02 Floor Plan MDP Architecture DA2 16/10/24\nDA106 Level 03 Floor Plan MDP Architecture DA2 16/10/24\nSCHEDULE 2\nDA107 Level 04 Floor Plan MDP Architecture DA2 16/10/24\nDA108 Level 05 Floor Plan MDP Architecture DA2 16/10/24\nDA109 Level 06 Floor Plan MDP Architecture DA2 16/10/24\nDA110 Level 07 Floor Plan MDP Architecture DA2 16/10/24\nDA111 Level 08 Floor Plan MDP Architecture DA2 16/10/24\nDA112 Roof Floor Plan 3A MDP Architecture DA2 16/10/24\nDA113 Roof Plan 3A MDP Architecture DA2 16/10/24\nDA201 East and West Site\nElevations\nMDP Architecture DA3 13/04/26\nDA202 North and South Site\nElevations\nMDP Architecture DA3 13/04/26\nDA203 Stage 3A Elevations MDP Architecture DA3 13/04/26\nDA204 Stage 3B Elevations MDP Architecture DA3 13/04/26\nDA205 Stage 3C Elevations MDP Architecture DA3 13/04/26\nDA301 East West Site Section MDP Architecture DA3 13/04/26\nDA302 Stage 3A Sections MDP Architecture DA3 13/04/26\nDA303 Stage 3B Sections MDP Architecture DA3 13/04/26\nDA304 Stage 3C Sections MDP Architecture DA3 13/04/26\nDA401 Area Plans and ADG\nCompliance - 3A\nMDP Architecture DA3 13/04/26\nDA402 Area Plans and ADG\nCompliance - 3B\nMDP Architecture DA3 13/04/26\nDA403 Area Plans and ADG\nCompliance - 3C\nMDP Architecture DA2 16/10/24\nDA404 3A/3B Apartment\nDesign Guide\nCompliance and 3C GFA\nMDP Architecture DA3 13/04/26\nDA601 Shadow Diagram - 9am,\nExisting/Proposed - 22\nJune\nMDP Architecture DA2 16/10/24\nDA602 Shadow Diagram -\n12pm,\nExisting/Proposed - 22\nJune\nMDP Architecture DA2 16/10/24\nDA603 Shadow Diagram - 3pm,\nExisting/Proposed - 22\nJune\nMDP Architecture DA2 16/10/24\nDA604 Solar Access 22 June MDP Architecture DA2 16/10/24\nLA01 Landscaping - Site Plan TaylorBrammer B 24/10/24\nLA02 Planting Plan - Ground\nLevel\nTaylorBrammer B 24/10/24\nLA03 Planting Plan - Roof\nLevel\nTaylorBrammer B 24/10/24\nLA04 Detail Plan and Section -\nWater Play and Plaza\nTaylorBrammer P2 24/10/24\nLA05 Typical Detail Plan and\nSection - Townhouse\nTaylorBrammer B 24/10/24\nLA06 Landscape Sections -\nRoof Level\nTaylorBrammer B 24/10/24\nLA07 Planting Character and\nSchedule\nTaylorBrammer A 24/10/24\nStatement of\nEnvironmental Effects\nSalvestro Planning 3.0 4/11/24\nFlood Impact\nAssessment (as\namended by the letter\nof 17/4/25 and as\namended by letter of\n27/11/25)\nNorthrop B 18/10/24\nLetter - Response to RFI Angus Brien, Northrop 17/04/25\nLetter - Submission of\nAdditional Information\n(excluding Attachment\nB)\nDavid Hunter, Habitat\nPlanning\n27/11/25\nLoading and\nOperational Waste\nManagement Plan\nMDP Architecture V3 23/10/24\nArborist Report Mark D McCrone\nLandscape Architect\nFeb 2024\nAnnexure E to the\nTraffic and Parking\nImpact Assessment\nMcLaren Traffic\nEngineering and Road\nSafety Consultants\nD 25/10/24\nThe Development Application has been determined by the granting of consent subject to and as\namended by the conditions of development consent specified below.\nNOTE: Any modifications to the proposal shall be the subject of an application under\nSection 4.55 of the Environmental Planning and Assessment Act, 1979.\nC.2 Consent is not granted under this consent for:\n(a) the car park works on Lot 1 DP 203835 (187 Morgan Street). Any car parking works on Lot 1 DP\n203835 shall be carried out under DA23/0340, as modified by the notice required under this\nconsent\n(b) any subdivision of land\n(c) any signage (other than signage that may be erected as Exempt Development under State\nEnvironmental Planning Policy (Exempt and Complying Development) 2008)\nC.3 The development shall be constructed over two stages, the first stage being Stage 3C, and\nthe second stage being Stage 3A/3B, as set out below:\nStage 3C:\n• Demolition of dwellings, outbuilding and infrastructure and tree removal at 66-72 Murray\nStreet\n• Construction of Building 3C:\n• Associated fencing and landscaping works.\n• Rear access for townhouses.\n• Loading bay for Building 3B.\n• Turning bay.\nStage 3A/3B:\n• Demolition of buildings and infrastructure and tree removal at 185 Morgan Street.\n• Construction of Building 3A including basement carparking shared with Building 3B.\n• Construction of Building 3B.\n• Associated landscaping.\n• Access and service road.\n• 5 at-grade parking spaces.\n• Modification of service road access off Morgan Street.\nNotwithstanding Plan DA071, the loading bay for Building 3B may be deferred to Stage 3A/3B.\nStage 3C shall be completed prior to, or concurrently with Stage 3A/3B.\nRequirements before a Construction Certificate can be issued\nC.4 Prior to the issue of Construction Certificate the applicant must lodge a bond with Council\nof:-\n$2000 for security deposit on the kerb and gutter and footpath\nPlus a non-refundable administration fee as per Council's Fees and Charges.\nNOTE 1: Applicants will be required to complete the Kerb Guttering and Footpath bond\nform and return to Council to arrange a bond (BKG) number. This must be done\nPRIOR to making payment at Council’s Customer Service desk. The form can be\nfound at <https://wagga.nsw.gov.au/__data/assets/pdf_file/0011/84188/Kerb-\nGuttering-and-Footpath-Bond-Form-Interactive.pdf>.\nNOTE 2: In lieu of payment, the applicant can with written authorisation from their builder,\nutilise an ongoing bond should their builder hold and ongoing bond.\nNOTE 3: All monetary conditions are reviewed annually, and may change on 1 July each\nyear.\nNOTE 4: Works in the form of driveways, kerb and gutter and footpath may require you to\nobtain a Section 138 Roads Act 1993 approval. Please contact Councils Road\nReserve Officer on 1300 292 442 prior to undertaking such works.\nNOTE 5: Council will accept a once off security deposit for the kerb and gutter and footpath\nfor applicants who lodge multiple DA‘s with council. If the applicant has security\ndeposits held by Council for kerb and gutter and footpath at the time of\nConstruction Certificate application, then Council may waive the need for an\nadditional bond to be paid.\nNOTE 6: The bond held on the kerb and gutter and footpath is fully refundable upon\ncompletion of all works and upon inspection by Council to ensure that any damage\nto Council infrastructure has been repaired. The bond will not be refunded in the\nevent that damage done to Council‘s infrastructure is not repaired to the\nsatisfaction of Council. All damage is to be repaired at the full cost of the applicant\nC.5 DELETED\nC.6 Prior to the release of Construction Certificate for each stage a compliance certificate under\ns306 of the Water Management Act 2000 for water supply related requirements must be\nobtained from Riverina Water in respect of the development relating to water management\nworks that may be required in connection with the relevant stage of the development. A\ncopy of the compliance certificate shall be provided to the Principal Certifying Authority prior\nto the release of each Construction Certificate.\nC.7 Prior to the release of the Construction Certificate for Stage 3A/3B, a Pedestrian Access\nand Mobility Plan (PAMP) showing a pedestrian access strategy to/from and within the site,\nshall be submitted to Council, to the satisfaction of the General Manager or delegate. The\nPAMP shall ensure that pedestrian linkages to/from Morgan St, car parking areas (including\nwithin the service road and on adjoining land) and the Active Travel network are included in\nthe development and that these linkages provide clearly defined and easily accessible\naccess for all users. Consideration should be given to any measures required in relation to\nthe underground car park access, loading bays, and turning bays to improve pedestrian\nsafety.\nNOTE: The pedestrian crossing indicated on the plans may not meet warrants in this\nlocation and alternative treatments should be considered to facilitate pedestrian\nmovements across the Morgan St service road.\nC.8 Prior to the release of the Construction Certificate for each stage, detailed plans of all works\nin the road reserve proposed to be carried out in conjunction with the stage shall be\nsubmitted to Council, for approval, to the satisfaction of the General Manager or delegate.\nThis shall include:\n(a) Any signage, linemarking and works including for any on street loading bays and turning\nbays.\n(b) In Stage 3A/3B signage to prohibit right turns from the Morgan Street service road to\nMorgan Street via the new access point between the two roadways, and to restrict vehicle\nmovements at this access point to exit only.\n(c) In Stage 3A/3B signage to control and direct the direction of traffic within the service road.\n(d) In Stage 3A/3B, any measures in the approved PAMP.\nNOTE: Any plan which includes a Traffic Control Device, subject to delegations, may\nrequire referral to, and approval by the Local Transport Forum (LTF) prior to\ninstallation. Other signage or linemarking may require notification to the LTF after\ninstallation. Council will advise, which matters, if any need to be reported to the\nLTF in the sign off of this condition.\nThe LTF meet approximately every six weeks. Therefore to avoid delays in the\nevent that a referral to the Local Transport Forum is required, the timing of\nmeetings should be taken into consideration in preparing your works schedule.\nC.9 Prior to the release of the Construction Certificate for each stage, a Construction\nManagement Plan (CMP), shall be submitted to Council, to the satisfaction of the General\nManager or delegate.\nThe CMP shall include details for parking of trades/workers/construction vehicles, material storage\nareas, site access arrangements (including site access control), delivery arrangements, noise and\nvibration management, dust and mud mitigation, site security, and complaint management\n(including methods for residents to raise concerns directly with the site manager).\nThe CMP shall be a document prepared exclusively for the purpose of this condition, addressing the\nmatters highlighted in this condition, and shall not form part of a more extensive document that\nincludes matters beyond the scope of Council, such as workplace safety.\nC.10 Prior to the issue of a Construction Certificate for each stage, a pre-construction\ndilapidation report shall be prepared by a suitably qualified person. The report shall include\nclear photos and descriptions of all existing public infrastructure adjacent to the subject site.\nA copy of the dilapidation report shall be submitted to and shall be approved by Council, to\nthe satisfaction of the General Manager or delegate.\nC.11 Prior to the issue of a Construction Certificate for stage 3A/3B:\n(a) Amended plans shall be submitted to the Principal Certifying Authority (with a copy forwarded\nto Council for Council’s records), extending the shop front glazing on Building 3B along the\nMorgan Street frontage of the building, consistent with the shop front glazing to Morgan Street\nprovided on Building 3A.\n(b) Plans shall be submitted to the Principal Certifying Authority (with a copy forwarded to Council\nfor Council’s records), demonstrating compliance with the minimum ceiling height\nrequirements of 4C1 of the Apartment Design Guide.\n(c) Amended plans shall be submitted to Council, to the satisfaction of the General Manager or\ndelegate, demonstrating direct vehicular access to the residential waste room in Building 3B, or\nalternatively, submission, to the satisfaction of the General Manager or delegate, detailing how\nwaste collection from the residential waste room in Building 3B will occur.\n(d) Plans and details shall be submitted to Council, to the satisfaction of the General Manager or\ndelegate, of signage (such as TfNSW sign R5-33) to be placed on the site to restrict access to the\ntwo service lanes to the maximum sized vehicles for which swept paths have been\ndemonstrated.\n(e) A Flood Emergency Response Plan (FERP) for the development shall be submitted to Council, to\nthe satisfaction of the General Manager or delegate. The FERP shall (as a minimum):\n• Set out protocols and procedures for the site in the event of both riverine and local\ncatchment flooding to minimise the risk to occupants of the land, including persons\nmoving onto and off the site;\n• Set out protocols to prevent entry into the basement car park during a flood event (both\nriverine and local catchment), from both within the buildings, and from offsite, up to and\nincluding a PMF event; and\n• Cover all development on the site (Stage 3A/3B) and shall include measures to ensure\noccupants (including any short stay occupants) are aware of these arrangements.\n(f) An amended plan and details demonstrating:\ni. Electric circuitry to accommodate ‘Level 2’ or higher standard electric vehicle charging\npoints to ensure that 100% of car spaces can install electric vehicle charging points in the\nfuture. This must include:\nA. Ensuring adequate electrical capacity and infrastructure (cable size, distribution\nboard size etc.) for the electric vehicle charging point system; and\nB. Providing either buried cables underground or cable trays sufficient to\naccommodate electric circuitry to each car space.\nii. Provision of an EV distribution board or boards of sufficient size to allow connection of all\nEV Ready connections.\niii. Locating EV distribution boards so that no future EV Ready connection will require a cable\nof more than 50 metres from the parking bay to connect.\niv. Demonstrating the future installation location of the cable trays from the EV distribution\nboard to the car spaces allocated to each dwelling. Spatial allowances are to be made for\ncables trays and EV Distribution Board(s) when designing in other services.\nv. 3 non-private (i.e. shared) parking spaces with a ‘Level 2’ or higher standard electric vehicle\ncharging point.\nThese plans and details shall be certified by a suitably qualified person (such as an electrical\nengineer) and be submitted to the Principal Certifying Authority (with a copy forwarded to\nCouncil for Council’s records).\nNOTE: “EV Ready” involves ensuring the installation of appropriate electrical circuitry to allow\nfor future electric vehicle charging points, by pre-wiring. This does not require the installation\nof a charging point.\nC.12 Prior to the release of the Construction Certificate for Stage 3C:\n(a) Amended plans, shall be submitted to and approved by the Principal Certifying Authority (with\na copy forwarded to Council for Council’s records), showing the front fences of the townhouse\nto Murray Street and the side fence to Morgan Street, no greater than 1800mm in height.\n(b) Details of the front fence panels, including aperture and overall openness percentage (no less\nthan 50% open), to the satisfaction of the General Manager or delegate, shall be submitted to\nCouncil for approval.\n(c) Amended plans, shall be submitted to and approved by the Principal Certifying Authority (with\na copy forwarded to Council for Council’s records), showing the dividing walls between each\ntownhouse, in the front setback area, no greater than 1800mm in height. Note, the wall may\nrise generally with the level of the adjacent steps, so that it tapers up and retains 1800mm in\nheight at the front face of the dwellings.\nC.13 On completion of demolition of existing buildings, concrete slabs and associated structures\nin each stage (both Stage 3C and Stage 3A/3B) but prior to any construction works, or the\nrelease of a Construction Certificate for each stage, further site contamination investigation\nwhich includes soil sampling, must be undertaken to address the uncertainty identified in\nthe Detailed Site Investigation. The further investigation must take the form of a\nSupplementary Detailed Site Investigation and must be prepared by an environmental\nconsultant certified under a NSW EPA recognised scheme.\nThe investigation and report must be undertaken in accordance with relevant NSW EPA Guidelines\nincluding, but not limited to “Consultants reporting on contaminated land: Contaminated land\nguidelines.” The investigation must also meet the requirements of the National Environment\nProtection Measure - Assessment of Site Contamination (NEPM).\nThe Supplementary Detailed Site Investigation must include an assessment of the suitability of the\nland for the proposed land use and outline remedial measures that may be required to ensure the\nsite is suitable for the proposed use. The Supplementary Detailed Site Investigation Report must be\nsubmitted to Council, to the satisfaction of the General Manager or delegate, prior to the\ncommencement of any works beyond demolition, and prior to the release of the Construction\nCertificate for each stage.\nC.14 Following the completion and reporting of the Supplementary Detailed Site Investigation in\neach stage, if the Supplementary Detailed Site Investigation identifies the need for\nremediation works, or in the opinion of the General Manager or delegate, remediation\nworks are required, a Remedial Action Plan must be prepared by an environmental\nconsultant certified under a NSW EPA recognised scheme to address the results and\noutcomes of the supplementary detailed investigation.\nThe Remedial Action Plan, must be submitted to Council, to the satisfaction of the General\nManager or delegate, prior to construction and issue of any Construction Certificate for both Stage\n3C and 3A/3B.\nC.15 If remediation works are required, the site must be remediated in each stage in accordance\nwith the Remedial Action Plan developed for each stage.\nOn completion of remedial works in each stage, a Validation Report must be prepared by an\nappropriately qualified, experienced and certified environmental consultant in accordance with\nrelevant NSW EPA guidelines including, but not limited to, the NSW EPA Guidelines “Consultants\nreporting on contaminated land: Contaminated land guidelines.”\nThe certified environmental consultant must be certified under a NSW EPA recognised scheme.\nThe Validation Report must verify that the site (as it relates to that stage) has been remediated in\naccordance with the Remedial Action Plan and also verify that the site is suitable for the proposed\ndevelopment.\nThe Validation Report must be reviewed by a NSW EPA accredited site auditor and a Section A1 Site\nAudit Statement provided, verifying that the site is suitable for commercial and residential use. The\nValidation Report and Site Audit Statement must be provided to Council, within 60 days of the\ncompletion of the remediation works and prior to Construction and issue of the Construction\nCertificate for the relevant stage.\nC.16 Pursuant to section 4.17(1)(b) and (5) of the Environmental Planning and Assessment Act\n1979, Condition C.1 of DA23/0340 shall be modified to amend the approved plans so the\ncar park layout on Lot 1 DP 203835 (187 Morgan Street) is consistent with the plans\nsubmitted under this Development Application.\n(1) Plans, to the satisfaction of the General Manager or delegate, shall be submitted to\nCouncil, to supersede drawing DA0110 “Car Park Proposed” and drawing DA0120 “Car Park\nDetails” approved under C.1 of DA23/0340, with replacement drawings showing the same\ndetail, altering the layout for Lot 1 DP 203835 (187 Morgan Street) is consistent with the\ndetails and plans submitted under this Development Application.\n(2) Following advice of the satisfaction of part (1) of this condition, submission of a clearly\nidentified draft notice, to the satisfaction of the General Manager or delegate, prepared in\naccordance with Clause 67 of the Environmental Planning and Assessment Regulation 2021.\n(3) Following advice of the satisfaction of part (2) of this condition, submission of a notice\n(consistent with the draft in part (2), as amended as per any advice from Council), to the\nsatisfaction of the General Manager or delegate, prepared in accordance with Clause 67 of\nthe Environmental Planning and Assessment Regulation 2021.\nC.17 Prior to the issue of each Construction Certificate, the plan relevant to that stage must\nclearly identify the structural pavement design for any internal driveway/vehicular\naccessway within the development site, and any works proposed in the Morgan Street\nservice road and carpark. The Construction Certificate plans must specify that the\npavement to be constructed as a concrete or asphalt sealed pavement accompanied by a\nPavement Design Report, prepared and certified by a suitably qualified Civil/Geotechnical\nengineer demonstrating compliance with Council’s Engineering Guidelines for Development\n& Subdivision and AUSTROADS standards and taking into account existing site subgrade\nconditions for approval as part of the Construction Certificate documentation. The plans\nshall be submitted to Council for approval, to the satisfaction of the General Manager or\ndelegate.\nC.18 Prior to the issue of each Construction Certificate sewer plans shall be submitted to Council\nfor approval. The plans shall detail extension of sewer mains to service the development.\nAny upgrade or augmentation of existing sewer mains to cater for the increased load\ngenerated from the development shall be taken into account in the design.\nC.19 Prior to the issue of each Construction Certificate stormwater plans shall be submitted to\nCouncil for approval. Stormwater mains shall be designed in accordance with Council’s\nEngineering Guidelines for Development & Subdivision. Overland flow paths shall be\nindicated on the plans for storm events which exceed the capacity of the stormwater\nsystem.\nC.20 Prior to the issue of each Construction Certificate, the plans must clearly identify vehicle\ncrossovers within the road reserve to be constructed in accordance with Council’s standard\ndrawing for an industrial/commercial vehicular crossing (Drawing EDS 02.09) contained\nwithin the Engineering Guidelines for Subdivisions and Development Standards.\nC.21 Prior to the issue of each Construction Certificate, engineer’s certification shall be\nsubmitted to Council, to the satisfaction of the General Manager or delegate.\nThe certification shall be from a qualified structural/civil engineer stating that the building if\nconstructed in accordance with the plans and specifications to which the Construction Certificate\nrelates, will not sustain structural damage from the force of flowing floodwaters or from impact of\ndebris associated with the floodwaters in a 1:100 year flood event.\nC.22 Prior to the release of each Construction Certificate, plans shall be submitted with the\nConstruction Certificate shall identify a minimum finished floor level for the habitable\ncomponents of the buildings and dwellings of 300mm above the 1% Annual Exceedance\nProbability flood event, given in metres AHD. The relevant level is 179.50m AHD.\nThe plans shall also certify the building will be of flood resilient design in accordance with the NSW\nReconstruction Authorities Flood Resilient Design Guide.\nC.23 Prior to the release of the Construction Certificate for Stage 3A/3B, plans submitted to\nCouncil, to the satisfaction of the General Manager or delegate, showing the underground\ncar park protected from inundation in a 1% Annual Exceedance Probability flood event\n(plus 300mm). The relevant level of protection required to be achieved is 179.50m AHD.\nC.24 Prior to the release of the Construction Certificate for Stage 3C, a Street Tree masterplan\nshowing the location of all proposed street trees, and the stage they are proposed to be\ndelivered in, shall be submitted for approval by the General Manager or delegate.\nC.25 Prior to the release of the Construction Certificate for each stage, an amended landscape\nplan for the stage shall be submitted to Council, to the satisfaction of the General Manager\nor delegate. The plan shall include:\n(a) Amended species selection, generally consistent with Council’s Landscape Guidelines.\n(b) Where plaza and front setback works are proposed in Stage 3A/3B, details of proposed\nfurniture, seating and final surface treatments within the front setback areas and plaza.\n(c) Where works are proposed within the road reserve, the works shall comply with Council’s\ndocument “Landscaping of Nature Strips”.\nRequirements before the commencement of any works\nC.26 If the work involved in the erection or demolition of a building or structure:\na) is likely to cause pedestrian or vehicular traffic in a public place to be obstructed or\nrendered inconvenient, or\nb) building involves the enclosure of a public place,\na hoarding or fence must be erected between the development site/works and the public place\nprior to works commencing on site.\nAll construction materials, waste, waste skips, machinery and contractors vehicles must be located\nand stored or parked within the site. No storage of materials, parking of construction machinery or\ncontactor’s vehicles will be permitted within the public space.\nIf necessary, an awning must be erected, sufficient to prevent any substance, from or in connection\nwith the work, falling into the public place. Further the work site must be kept lit between sunset\nand sunrise if it is likely to be hazardous to persons in the public place.\nNOTE 1: Any such hoarding, fence or awning must be removed when the work has been\ncompleted.\nNOTE 2: Any external lighting required by this condition must be designed and positioned so\nthat, at no time, will any light be cast upon any adjoining property.\nNOTE 3: Prior to any hoarding being erected, the applicant must ensure that an application\nfor a Hoarding Permit is submitted to and approved by Council.\nC.27 Prior to works commencing on site, toilet facilities must be provided, at or in the vicinity of\nthe work site on which work involved in the erection or demolition of a building is being\ncarried out, at the rate of one toilet for every 20 persons or part of 20 persons employed at\nthe site. Each toilet provided must be:\na) a standard flushing toilet connected to a public sewer, or\nb) if that is not practicable, an accredited sewage management facility approved by Council,\nor\nc) if that is not practicable, any other sewage management facility approved by Council.\nNOTE 1: The provision of toilet facilities in accordance with this condition must be\ncompleted before any other work is commenced and the toilet facility must not be\nremoved without the prior written approval of Council.\nNOTE 2: “Vicinity” in this condition is defined to mean within 50 metres of the subject\nbuilding site.\nNOTE 3: The toilet facilities are to comply with all WORK COVER NSW requirements.\nC.28 Prior to the commencement of works for each stage, a Construction Certificate must be\nobtained, pursuant to Section 6.7 of the Environmental Planning and Assessment Act 1979,\nas amended, from Council or an Accredited Certifier.\nDemolition works to facilitate Detailed Site Investigations and remediation works can commence in\nthe absence of a Construction Certificate, subject to a Construction Management Plan under\nCondition C.9 being approved, and all prior to commencement of works conditions being complied\nwith.\nC.29 Prior to works commencing a container must be erected on site for the enclosure of all\nbuilding rubbish and debris, including that which can be wind blown. The enclosure shall be\napproved by Council and be retained on site at all times prior to the disposal of rubbish at a\nlicenced Waste Management Centre.\nMaterials and sheds or machinery to be used in association with the construction of the building\nmust not be stored or stacked on Council’s footpath, nature strip, reserve or roadway.\nNo building rubbish or debris shall be placed, or be permitted to be placed on any adjoining public\nreserve, footway, road or private land.\nWeighbridge certificates, receipts or dockets that clearly identify where waste has been deposited\nmust be retained. Documentation must include quantities and nature of the waste. This\ndocumentation must be provided to the Principal Certifying Authority prior to application for an\nOccupation Certificate for the development.\nThe suitable container for the storage of rubbish must be retained on site until an Occupation\nCertificate is issued for the development.\nAll reasonable steps must be taken to ensure that dust from the construction and demolition\nactivities on site is kept to a minimum. This includes wetting down disturbed soils and providing\nadequate cover.\nC.30 Prior to the commencement of works erosion and sediment control measures are to be\nestablished and maintained to prevent silt and sediment escaping the site or producing\nerosion. This work must be carried out and maintained in accordance with Council’s:-\na) Development Control Plan 2010 (Section 2.6 and Appendix 2)\nb) Erosion and Sediment Control Guidelines for Building Sites; and\nc) Soils and Construction Volume 1, Managing Urban Stormwater\nA plan illustrating these measures shall be submitted to, and approved by, the Principal Certifying\nAuthority. The approved erosion and sediment control measures must be in place prior to\nearthworks commencing.\nC.30A All vehicles involved with the construction and/or demolition process and departing the property\nwith demolition material, spoil, debris and loose material must have their loads covered before\nentering the public road. Suitable measures shall be in place to ensure that sediment is not tracked\nonto the roadway by vehicles leaving the site. This may require the installation of an all-weather\ntemporary driveway for all construction vehicles accessing and leaving the site.\nIt is an offence to allow, permit or cause materials to pollute waters.\nC.31 No works are to take place to any services without prior written approval from the relevant\nauthority.\nNOTE: Underground assets may exist in the area that is subject to your application. In the\ninterests of health and safety and in order to protect damage to third party assets\nplease contact Dial before you dig at www.1100.com.au\n<http://www.1100.com.au> or telephone on 1100 before excavating or erecting\nstructures.\nC.32 Prior to works commencing in the Road Reserve a pre-start meeting shall be held with\nCouncil’s Development Engineer. Contact Council’s Development Engineer on 1300 292\n442.\nC.33 Prior to works commencing on site:\ni) Council must be notified of any damage to kerb and gutter and footpath fronting\nthe site. The absence of such notification shall indicate that no damage exists and\nthe applicant shall be responsible for the repair of any damage to kerb and gutter\nor footpath fronting the site.\nii) Satisfactory protection for existing public infrastructure must be provided and\nmaintained throughout the construction period.\nC.34 Prior to the issue of any Complying Certificate for the concrete floor slab for each building\napproved under this consent, the Principal Certifying Authority shall receive documentation\nfrom a registered surveyor certifying that the floor of each building's habitable rooms (and in\nthe case of Building 3A, in addition, any berm or embankment protecting the underground\ncar park) will have a finished floor level (or in the case of any car park protection, a finished\nlevel) that is 300mm above the inundation level caused by the 1:100 ARI flood event at the\nlocation of the development. The required floor level is 179.50m AHD.\nNOTE: It is recommended that prior to commencement of any works, a registered\nsurveyor establish an appropriate benchmark on the site from which construction\nlevels can be conveyed. The surveyor should then confirm the floor level once\nformwork is in place and ready for the pouring of the floor slabs.\nC.35 Required pruning maintenance to Council street trees shall be carried out by Council or an\napproved contractor of Council at full cost to the applicant. Council is to be notified of any\ncontractor prior to the commencement of works.\nPruning shall be carried out in accordance with Australian Standards AS 4373-2007 Pruning of\nAmenity Trees.\nC.36 Tree removal works shall be carried out by an approved contractor at full cost to the person\ncarrying out the development. Council is to be notified of contractor details prior to the\ncommencement of works.\nTree removal consent only applies to this proposed development. If the development is not\ncommenced the subject street tree/s shall be retained on the road reserve.\nTree stump/s shall be removed below ground level to a depth of 300mm and surface area\nreinstated to prevent potential injury. Dial before you dig shall be undertaken before the removal\nof tree/s stumps to prevent damage to underground services.\nC.37 No trees shall be removed from the site unless they have been clearly identified and\nmarked on the approved plans for removal, or approval has otherwise been granted by\nCouncil.\nC.38 A Tree Protection Zone (TPZ) shall be constructed for all existing trees to be retained within\nthe development (including the English Elm adjacent to the site at 80 Murray St), as\nrelevant to the stage of construction, in accordance with Australian Standards - AS 4970-\n2009 Protection of Trees on Development Sites.\nConstruction of Tree Protection Zones shall be completed and inspected by Council’s Supervisor of\nTree Planning and Management, prior to the commencement of any site works. Contact can be\nmade by phoning 1300 292442 during normal business hours.\nTree Protection Zone fencing shall not be relocated or disrupted once established. TPZ fences shall\nremain in place until the end of construction.\nC.39 All street trees in proximity to works being carried, and that are to be retained, are to be\nisolated from the work site. Prior to the commencement of works in each stage, temporary\nfencing, with a minimum height of 1.8 metres, shall be installed to surround the entire tree.\nThe fencing shall not extend beyond the kerb or footpath, with these areas are to remain\nobstruction free for the duration of works.\nC.40 Prior to the commencement of works , an Activity Approval is required under Section 68,\nPart B - 4, 5 and 6, of the Local Government Act 1993 for any public infrastructure sewer /\nstormwater works, where that work is proposed to be carried out on private or Council\nowned land. Works that require a Section 68 (PUBLIC) approval include:\ni) Extension and connection of stormwater pipes serving the development to Councils\nstormwater system\nii) Extension of sewer mains to service the development. Any upgrade or\naugmentation of sewer mains to cater for the increased load generated from the\ndevelopment shall be at full cost to the developer.\niii) Provision of a sewer spur to each townhouse in Stage 3C, and any redundant spurs\ndecommissioned\nNOTE 1: Works carried out under an approved Section 68 prior to a Development Consent\nand/or Construction Certificate being issued are subject to change and are at the\napplicant’s risk.\nNOTE 2: Prior to the commencement of works a bond may be required to be lodged with\nCouncil for public infrastructure works. Refer to Council’s Section 68 Activity\nApproval Application Guide for detail.\nC.41 A Section 68 Approval must be obtained from Council prior to any sewer or stormwater\nwork being carried out on the site.\nThe licensed plumber must submit to Council, at least two (2) days prior to the commencement of\nany plumbing and drainage works on site a “Notice of Works”.\nNOTE: A copy of the Notice of Works form can be found on Council’s website.\nC.42 Prior to works or activities commencing within the road reserve, approval under Section 138\nof the Roads Act 1993 is required from Council.\nA written application for Consent to Work on a Road Reserve is required to be submitted to and\napproved by Council. This shall include the preparation of a certified Temporary Traffic\nManagement Plan (TTP) and submission of engineering plans for the works.\nIt should be noted that work in the existing road reserve can only commence after the plan has\nbeen submitted and approved and then only in accordance with the submitted TTP. Please contact\nCouncil’s Activities in Road Reserves Officer on 1300 292 442.\nRequirements during construction or site works\nC.43 No construction materials, plant or equipment relating to work authorised by this consent\nare to be placed or stored within the road reserve during the period in which work\nauthorised by this consent will be carried out without the prior written approval of the\nCouncil.\nC.44 If an excavation associated with the erection/demolition of a building extends below the\nlevel of the base of the footings of a building on an adjoining allotment of land, the person\ncausing the excavation to be made:\na) must preserve and protect the building from damage, and\nb) if necessary, must underpin and support the building in an approved method, and\nc) must, at least 7 days before excavating below the level of the base of the footings of a\nbuilding on an adjoining allotment of land, give notice of intention to do so to the owner of\nthe adjoining allotment of land and furnish particulars to the owner of the building being\nerected/demolished.\nNOTE 1: The owner of the adjoining allotment of land is not liable for any part of the cost of\nthe work carried out for the purposes of this condition, whether carried out on the\nallotment of land being excavated or on the adjoining allotment of land.\nNOTE 2: For the purposes of this condition allotment of land includes a public road or any\nother public place.\nC.45 All excavation and backfilling associated with the erection/demolition of the building must\nbe properly guarded and protected to prevent them from being dangerous to life or\nproperty.\nC.46 The demolition must be carried out in accordance with the provisions of Australian\nStandard AS2601-2025: The Demolition of Structures.\nWithin fourteen (14) days of completion of demolition, the following information shall be\nsubmitted to the Principal Certifying Authority:\na) an asbestos clearance certificate prepared by a competent person; and\nb) a signed statement verifying that demolition work and the recycling of materials was\nundertaken in accordance with any Waste Management Plan approved with this consent.\nIn reviewing such documentation Council will require the provision of actual weighbridge\nreceipts for the recycling/disposal of all materials.\nNOTE 1: Developers are reminded that WorkCover requires that all plant and equipment\nused in demolition work must comply with the relevant Australian Standards and\nmanufacturer specifications.\nNOTE 2: Demolition works involving the removal and disposal of asbestos cement must only\nbe undertaken by contractors who hold a current WorkCover “Demolition Licence”\nand a current WorkCover “Class 2 (Restricted) Asbestos Licence”.\nNOTE 3: Competent Person (as defined under Safe Removal of asbestos 2nd Edition\n[NOHSC: 2002 (2005)] means a person possessing adequate qualifications, such as\nsuitable training and sufficient knowledge, experience and skill, for the safe\nperformance of the specific work.\nNOTE 4: A licence may be required for some of the tasks described in the document entitled\nSafe Removal of Asbestos 2nd Edition as requiring a competent person.\nC.47 The permitted construction hours are Monday to Friday 7:00am to 6:00pm and Saturday\n7:00am to 5:00pm, excepting public holidays. All reasonable steps must be taken to\nminimise dust generation during the demolition and/or construction process. Demolition and\nconstruction noise is to be managed in accordance with the NSW Environment and\nHeritage Guidelines.\nC.48 All earthworks, filling, building, driveways or other works, must be designed and\nconstructed (including stormwater drainage if necessary) so that stormwater impacts on\nadjoining properties are no greater than the impacts identified in the Flood Impact\nAssessment, Revision B, and prepared by Northrop, and dated 18/10/24.\nC.49 No fill shall be imported to the site. Any excavated material removed from the site shall be\nclassified and must only be taken to a site approved for the receipt of such material.\nC.50 The following requirements of Essential Energy must be complied with:\n1. Any existing encumbrances in favour of Essential Energy (or its predecessors) noted on the title\nof the above properties should be complied with.\n2. Essential Energy’s records indicate there is electricity infrastructure located within the\nproperties and within close proximity to the properties. Any activities within these locations\nmust be undertaken in accordance with the latest industry guideline currently known as ‘ISSC\n20 Guideline for the Management of Activities within Electricity Easements and Close to\nInfrastructure’. Approval may be required from Essential Energy should activities within the\nproperties encroach on the electricity infrastructure.\n3. Given there is electricity infrastructure in the area, it is the responsibility of the person/s\ncompleting any works around powerlines to understand their safety responsibilities. SafeWork\nNSW (www.safework.nsw.gov.au) has publications that provide guidance when working close\nto electricity infrastructure. These include the’ Code of Practice - Work near Overhead Power\nLines’ and ‘Code of Practice - Work near Underground Assets’.\nC.51 If unexpected soil and/or groundwater contamination is encountered during any works, all\nwork associated with that task must cease and the situation must be promptly evaluated by\na suitably qualified environmental consultant. The contaminated soil and/or groundwater\nmust then be managed under the supervision of the supervising environmental consultant,\nin accordance with the Unexpected Finds Protocol provided in the Remedial Action Plan\nand relevant NSW Environment Protection Authority (EPA) guidelines.\nPrior to recommencement of works, if unexpected contaminated soil or groundwater is treated\nand/or managed onsite; the supervising environmental consultant must verify that the situation\nwas appropriately managed in accordance with relevant NSW EPA guidelines. The verification\ndocumentation must be provided to the satisfaction of the NSW EPA accredited site auditor, prior\nto the recommencement of any works.\nC.52 Prior to the carrying out of any works that require pre-approval from the Local Transport\nForum (LTF) (as advised by Council in the approval of Condition C.8), the applicant must\nnotify Council’s Local Transport Forum (LTF) representative of the proposed works, and\nobtain the approval of the LTF to carry out the works.\nNOTE: The LTF meet approximately every six weeks. Contact with Council’s Senior Traffic\nOperations Engineer can be made by phoning 1300 292442 during normal business hours.\nC.53 Any upgrades or alterations to existing Council infrastructure required as a result of the\ndevelopment shall be at the full cost of the applicant. Contact Council’s Development\nEngineer to confirm what approval is required prior to commencing work on any Council\ninfrastructure. Such work includes (but is not limited to) upgrade or connection to sewer or\nstormwater mains, and alteration of stormwater pits and sewer manhole levels.\nC.54 A temporary security fence shall be provided to the perimeter of the site to prevent public\naccess during the construction phase. The temporary security fence shall not be erected in\nthe Council road reserve without an approved Section 138 Permit.\nC.55 Where works involve excavation, filling or grading of land, or removal of vegetation,\nincluding ground cover, dust is to be suppressed by regular watering until such time as the\nsoil is stabilised to prevent airborne dust transport. Where excessive dust generation is\noccurring due to high winds and/or dry conditions it may be necessary to temporarily cease\noperations.\nC.56 The developer is to maintain all adjoining public roads to the site in a clean and tidy state,\nfree of excavated “spoil” material.\nC.57 If any Aboriginal object is discovered and/or harmed in, on or under the land, all work must\ncease immediately and the area secured so as to avoid further harm to the Aboriginal\nobject. NSW Environment and Heritage shall be notified as soon as practicable on 131 555,\nproviding any details of the Aboriginal object and its location, and no work shall\nrecommence at the particular location unless authorised in writing by NSW Environment\nand Heritage.\nC.58 Trees indicated on the submitted plans for removal, shall be removed from the site in\naccordance with the proposed development. Further consent is not required for removal of\nthe subject trees in conjunction with this development.\nThe approved works shall be executed so as to comply with ‘Safework NSW Tree work\n(arboriculture)’\nAny works associated with tree removal shall be carried out in Accordance with Australian\nStandards - AS 4373-2007, Pruning of Amenity Trees.\nAll tree stumps shall be removed below ground level and the surface area reinstated to prevent\npotential injury.\nAll waste material from the subject tree/s shall be removed from site in conjunction with clearing.\nRequirements prior to issue of an Occupation Certificate or prior to operation\nC.59 Prior to issue of each Occupation Certificate the redundant kerb laybacks in Murray and\nMorgan Streets relevant to that stage shall be replaced with conventional barrier kerbing,\nand Council’s footway rehabilitated, in accordance with Council’s Engineering Guidelines\nfor Subdivisions and Developments.\nC.60 Prior to issue of an occupation certificate the building number must be displayed in a\nposition clearly visible from the street in letters having a height of not less than 75 mm. The\nnumber must be visible against the background on which it is placed.\nC.61 Prior to the issue of each Occupation Certificate, a maintenance bond equal to 5% of the\ntotal cost of civil works shall be paid. The bond shall be held for the duration of the\nmaintenance period until the works are accepted Out of Maintenance.\nC.62 Street trees shall be planted by Council following the payment of the fee under this\ncondition.\nAlternatively, street trees, consistent with the plan approved under Condition C.24 shall be planted\nby a Council approved contractor.\nPrior to the release of the Occupation Certificate for each stage:\n(1) Payment of the relevant fee per tree, as set out in Council’s Fees and Charges, shall be paid\nto Council, for street tree planting works to be carried out by Council; or\n(2) Payment of a bond, to be held by Council for two years, equivalent to the fee that would be\npayable under part (1), shall be paid to Council, for street tree works carried out by a\nCouncil approved contractor.\nIf trees are to be planted by a Council approved contractor the following information is to be\nsubmitted to Council for approval, to the satisfaction of the General Manager or delegate, prior to\nthe release of the Occupation Certificate:\n(a) Company trading name\n(b) Contractor‘s license number\n(c) Relevant experience of company\n(d) Relevant qualifications of key staff undertaking the works\nPlanting by a contractor can only occur during the next available planting season (May-August).\nC.63 Prior to the release of any Occupation Certificate for Stage 3C:\n1. Lots 1-4 DP 20847 (66-72 Murray Street) shall be consolidated (with evidence of the\nregistration of the Plan of Consolidation with NSW Land Registry Services submitted to the\nPrincipal Certifying Authority).\nAlternatively, if an alternate consolidation/subdivision of the land has been approved by\nCouncil, that in the opinion of the General Manager or delegate satisfactorily addresses any\nland tenure issues (as advised in writing), evidence of the registration of that plan, shall be\nsubmitted to the Principal Certifying Authority.\n2. A right of way in favour of Lot 1 DP 550746 (185 Morgan Street), and with Council empowered\nto uplift, shall be registered over the entirety of the service driveway to the rear of the\ntownhouses. Details of the right of way shall be provided to Council, to the satisfaction of the\nGeneral Manager or delegate, prior to registration. Evidence of the registration of the right of\nway shall be submitted to the Principal Certifying Authority.\nAlternatively, if in the opinion of the General Manager or delegate, suitable alternative\narrangements have been approved and are in place, which ensure enduring access for\nBuildings 3A and 3B over the driveway, the General Manager or delegate may advise in writing\nthat compliance with this condition is not required.\n3. A restriction as to user, requiring that the front fence panels maintain a minimum openness of\nat least 50%, unless agreed to in writing by the General Manager or delegate. Details of the\nrestriction as to user shall be provided to Council, to the satisfaction of the General Manager\nor delegate, prior to registration. Evidence of the registration of the restriction as to user shall\nbe provided to the Principal Certifying Authority.\nC.64 Prior to the release of any Occupation Certificate for Stage 3A/3B:\n1. Reciprocal rights of way, burdening and in favour of, Lot 1 DP 550746 (185 Morgan Street) and\nLot 1 DP 203835 (187 Morgan Street), with Council empowered to uplift, shall be registered\nover the entirety of the access route through the car park, and the service driveway west of\nBuilding 3A. Details of the rights of way shall be provided to Council, to the satisfaction of the\nGeneral Manager or delegate, prior to registration. Evidence of the registration of the right of\nway shall be submitted to the Principal Certifying Authority.\nAlternatively, if in the opinion of the General Manager or delegate, suitable alternative\narrangements have been approved and are in place (including the consolidation of the two\nsubject lots), which ensure enduring access for Buildings 3A and 3B, and vehicles using the\ncarpark, over both driveways, the General Manager or delegate may advise in writing that\ncompliance with this condition is not required.\n2. DELETED\n3. An easement for parking, burdening Lot 1 DP 203835 (187 Morgan Street) and benefiting Lot 1\nDP 550746 (185 Morgan Street), with Council empowered to uplift, shall be registered over all\nparking spaces in Lot 1 DP 203835 (187 Morgan Street). The easement shall require the car\npark is available for use by residents, tenants, visitors and customers of any premises on Lot 1\nDP 550746 and that the availability of parking spaces is not reduced. Details of the easement\nshall be provided to Council, to the satisfaction of the General Manager or delegate, prior to\nregistration. Evidence of the registration of the easement shall be submitted to the Principal\nCertifying Authority.\nAlternatively, if in the opinion of the General Manager or delegate, suitable alternative\narrangements have been approved and are in place (including the consolidation of the subject\nlots), which ensures ongoing access to the car park for residents, tenants, visitors and\ncustomers of any premises in Buildings 3A or 3B the General Manager or delegate may advise\nin writing that compliance with this condition is not required.\nC.65 A post construction report, prepared by a suitably qualified person, shall be prepared at the\ncompletion of construction of each stage. This report is to ascertain whether the\nconstruction created any structural damage to adjoining infrastructure.\nThe report shall include a comparison with the pre-construction dilapidation report required by\nthese conditions and have written confirmation from the relevant authority that there is no\nadverse structural damage to their infrastructure.\nThe report shall be submitted to and shall be approved by Council, to the satisfaction of the\nGeneral Manager or delegate, prior to the release of the Occupation Certificate for each stage.\nUnless the consent holder and the applicable authority agree otherwise, the Applicant must:\na) repair, or pay the full costs associated with repairing, any public infrastructure that is\ndamaged by carrying out the development; and\nb) relocate, or pay the full costs associated with relocating any infrastructure needs to be\nrelocated as a result of the development.\nC.66 Prior to the issue of each Occupation Certificate, all works external to the site and relevant\nto that stage (in the opinion of the General Manager or delegate), including any works\nincluding any works in the road reserve to facilitate access to the site for pedestrians and\nvehicles, including:\n⦁ any turning or loading bays,\n⦁ any works approved under the PAMP,\n⦁ Signage to direct and control the movement of vehicles (including any loading bay, no entry\nand no right turn signage)\nShall be completed or installed, to the satisfaction of the General Manager or delegate.\nFor any works that require notification to the Local Transport Forum (as advised by Council in the\napproval of Condition C.8) at the completion of the works, the applicant must notify Council’s LTF\nrepresentative that the works have been completed in accordance with the requirements of the\napproved plans. The notification must occur as soon as practicable after the works have been\ncompleted as there is a requirement to report all works to the LTF no later than three months after\ncompletion.\nNOTE: The LTF meet approximately every six weeks and require copies of the approved plans and\nevidence of completion. Contact with Council’s Senior Traffic Operations Engineer can be\nmade by phoning 1300 292442 during normal business hours.\nC.67 Prior to the issue of the Occupation Certificate for Stage 3A/3B, an ‘Ongoing Landscape\nand Building Maintenance Plan’ shall be submitted to Council, to the satisfaction of the\nGeneral Manager or delegate. The ongoing maintenance plan shall make enforceable\ncommitments regarding the maintenance/cleaning of the building, landscaping and public\nand semi-public areas, including:\na. routine cleaning and litter collection,\nb. sweeping,\nc. graffiti removal,\nd. replacement and repair of broken furniture/equipment/facilities in plaza areas,\ne. the cleaning and maintenance of the water play area,\nf. the pruning, weeding and general maintenance of landscape areas,\ng. the replacement of dead plants, and\nh. the general clean and tidy maintenance and keeping in good condition all public spaces and\nexternal facades.\nThe plan shall detail minimum standards for maintenance contracts and shall specify that such a\ncontract is in place at all times for the maintenance of external facades and landscaping, or\notherwise, clearly state who is responsible for maintenance.\nMaintenance of the external facades of the building and publicly accessible areas shall occur in\naccordance with the measures set out in the approved ‘Ongoing Landscape and Building\nMaintenance Plan’ unless otherwise agreed to, in writing, by the General Manager or delegate.\nFurthermore, the plan may be amended from time-to-time, with the consent of the General\nManager or delegate.\nFor the avoidance of doubt, the plan may be amended in future so that it is inconsistent with the\nrequirements of (a), (b), (c), (d), (e), (f), (g) and/or (h), if in the opinion of the General Manager or\ndelegate, circumstances have changed due to contemporary practices not envisaged at the time of\nthis consent.\nNOTE: This plan shall not seek to manage general building maintenance, building safety or\nupkeep, and only relates to the general cleanliness and presentation of external facades\nand landscaping.\nC.68 DELETED\nC.69 Prior to the release of the Occupation Certificate for Stage 3A/3B, an amended ‘Loading\nand Operational Waste Management Plan’ shall be submitted to Council for approval, to the\nsatisfaction of the General Manager or delegate, for the entirety of the buildings (including\ncommercial tenancies). The amended plan shall include provisions such as:\na. Requiring an agreement be in place for the collection of skip bins, and that individual\nwheelie bin/kerb side collection will not occur.\nb. Requiring that general waste, recycling bins, and FOGO bins will be available for use by all\nresidents and tenants (including facilities for sorting and collection in each apartment).\nc. A waste collection frequency consistent with waste storage capacity provided on site.\nd. The maximum sized vehicle to service any part of the development.\ne. General arrangements for deliveries, loading and unloading on the site and adjacent\nloading bays.\nWaste collection, loading and deliveries shall occur in accordance with the measures set out in the\napproved ‘Loading and Operational Waste Management Plan’, unless otherwise agreed to, in\nwriting, by the General Manager or delegate. Furthermore, the plan may be amended from time-\nto-time, with the consent of the General Manager or delegate.\nFor the avoidance of doubt, the plan may be amended in future so that it is inconsistent with the\nrequirements of (a) to (e), if in the opinion of the General Manager or delegate, circumstances have\nchanged due to contemporary loading, delivery and waste management practices not envisaged at\nthe time of this consent.\nC.70 DELETED\nC.71 Prior to the issue of the Occupation Certificate for Stage 3A/3B:\n(a) All landscaping works (including furniture, and the water play area) relevant to that stage shall\nbe completed to the satisfaction of the Principal Certifying Authority.\n(b) Details of the division of basement storage between units, and associated compliance with\n4G1 of the Apartment Design Guide for total storage space per unit, shall be submitted to\nCouncil, to the satisfaction of the General Manager or delegate.\n(c) Parking to service the development shall be available for use, including all linemarking and\nsignposting, to the satisfaction of the Principal Certifying Authority.\n(d) Signage to restrict the vehicles beyond the maximum length for which swept paths have been\nprepared from entering the site, as approved under C.11(d) shall be installed within the site, to\nthe satisfaction of the Principal Certifying Authority.\n(e) Confirmation (including certification where relevant, such as in relation to the design of lift\nsystems), to the satisfaction of the Principal Certifying Authority, from an appropriately\nqualified person that all measures to restrict basement carpark access as set out in the Flood\nEmergency Response Plan have been implemented.\n(f) A plan shall be submitted to Council, to the satisfaction of the General Manager or delegate,\nidentifying the allocation of the parking spaces for each unit, and appropriate\nsignage/linemarking to give force to the arrangements. Tandem parking spaces shall only be\nallocated to a single unit as a pair.\n(g) The car park approved under DA23/0340 (as amended) on Lot 1 DP 203835 (187 Morgan\nStreet) shall be constructed, to the satisfaction of the General Manager or delegate.\n(h) An Occupation Certificate shall be issued for the entirety of Stage 3C.\nC.72 Prior to the issue of each Occupation Certificate, the Principal Certifier must be provided\nwith documentary evidence demonstrating that\n• All internal driveway and vehicular access areas and,\n• Driveway crossover/s constructed within the road reserve (kerb to property boundary);\nhave been constructed in accordance with the approved Construction Certificate plans. Where the\napproved plans include an engineering pavement design, the documentary evidence must include\ncertification from the engineer that the driveway has been constructed in accordance with the\napproved pavement design. The Principal Certifier must be satisfied that compliance with this\ncondition has been demonstrated prior to issuing the Occupation Certificate.\nC.73 Prior to the issue of any Occupation Certificate for Stage 3C the proposed townhouses are\nto be adequately serviced.\ni) A sewer junction and spur must be provided to each of the townhouses from Councils\nsewer main.\nii) A stormwater spur from Council’s stormwater main shall be provided to each townhouse\nThe works shall be at the full cost of the developer and must be carried out by a Council approved\ncontractor. Works as Executed (WAE) plans shall be provided in accordance with Council’s\nGuidelines for Subdivision and Developments.\nNOTE: A Section 68 approval will be required for the works. The WAE plans shall show the location\nof the constructed mains/junctions and spurs to confirm they are servicing each townhouse.\nC.74 Prior to the issue of each Occupation Certificate for the completed development fees for\nCivil Works (including road works, stormwater, sewer, concrete works) inspections shall be\npaid in full. Inspections will be charged in accordance with Council’s current Fees and\nCharges Schedule.\nC.75 Prior to release of each Occupation Certificate for the completed development an “into\nmaintenance inspection” must be carried out of the completed works. The maintenance\nperiod will last for 6 months, upon which time an “out of maintenance inspection” will be\nrequired to ensure the works are acceptable to Council.\nC.76 Prior to the issue of each Occupation Certificate, the applicant shall provide to Council a\ncopy of the certification from the registered surveyor required under Condition C.34\nregarding the constructed floor level of the buildings, relevant to that stage.\nC.77 An Occupation Certificate, must be obtained pursuant to Section 6.9 of the Environmental\nPlanning and Assessment Act 1979, from either Council or an accredited certifying\nauthority, prior to occupation of each building.\nIn order to obtain this, the “Final Occupation Certificate” form must be completed and submitted\nto Council with all required attachments - failure to submit the completed Occupation Certificate\nApplication form will result in an inability for Council to book and subsequently undertake\nOccupation Certificate inspection.\nNOTE: The issuing of an Occupation Certificate does not necessarily indicate that all\nconditions of development consent have been complied with. The applicant is\nresponsible for ensuring that all conditions of development consent are complied\nwith.\nC.78 A final inspection must be carried out upon completion of plumbing and drainage work and\nprior to occupation of the development, prior to the issuing of a final plumbing certificate\nCouncil must be in possession of Notice of Works, Certificate of Compliance and Works as\nExecuted Diagrams for the works. The works as Executed Diagram must be submitted in\nelectronic format in either AutoCAD or PDF file in accordance with Council requirements.\nAll plumbing and drainage work must be carried out by a licensed plumber and drainer and to the\nrequirements of the Plumbing and Drainage Act 2011.\nNOTE: Additional fees for inspections at the Plumbing Interim Occupancy / Plumbing\nOccupation stage may apply. This will depend on the number of inspections\ncompleted at this stage of the work/s.\nC.79 Prior to the issue of an Occupation Certificate a Water Plumbing Certificate from Riverina\nWater County Council shall be submitted to Council.\nNOTE 1: The applicant is to obtain a Plumbing Permit from Riverina Water County Council\nbefore any water supply/plumbing works commence and a Compliance Certificate\nupon completion of the works. Contact Riverina Water County Council’s Plumbing\nInspector on 6922 0618. Please be prepared to quote your Construction Certificate\nnumber.\nC.80 Prior to the issue of an Occupation Certificate for Stage 3A/3B, signs must be erected that\nclearly indicate to drivers of vehicles, both on and off the subject land, the driveway by\nwhich they are to enter or leave the subject land.\nC.80A Pursuant to s7.11 of the Environmental Planning and Assessment Act 1979 and the Wagga Wagga\nLocal Infrastructure Contributions Plan 2019-2034, a monetary contribution as identified in the table\nbelow must be paid to Council, prior to the issuing of the Occupation Certificate for each stage. The\nmonetary contribution payable under this condition will be indexed in accordance with Clause 3.2 of\nthe Wagga Wagga Local Infrastructure Contributions Plan 2019-2034 from the endorsed date of this\nDevelopment Consent until the date of payment. Evidence in writing from Council must be provided\nconfirming the required contributions have been paid, to the satisfaction of the certifier.\nBase monetary contribution\n(Contribution Rate in Wagga Wagga\nLocal Infrastructure Contributions\nPlan 2019-2034)\n• $5,776 per one bedroom dwelling,\n• $7,702 per two bedroom dwelling and\n• $10,012 per three bedroom or larger\ndwelling.\nThe four existing dwellings each have a base credit of\n$10,012 which is applicable in stage 3C. 185 Morgan\nStreet has a base credit for 1 lot of $10,012 which is\napplicable in Stage 3A/3B.\nAdopted CPI indexation applied at\ndate of determination (as per\nSection 3.2 of Wagga Wagga Local\nInfrastructure Contributions Plan\n2019-2034)\n140.9/115.1\nIndexed monetary contribution to\nbe paid (valid for the financial year\nin which the date of determination\nwas made)\n• $7,071 per one bedroom dwelling,\n• $9,428 per two bedroom dwelling and\n• $12,256 per three bedroom or larger\ndwelling.\nThe credit for each existing dwelling/185 Morgan\nStreet is $12,256. (see Note 2)\nNOTE 1: Clause 3.2 of the Wagga Wagga Local Infrastructure Contributions Plan 2019 -2034\nprovides for Section 7.11 contributions to be indexed in accordance with annual\nmovements in the March quarter Consumer Price Index (CPI) (All Groups Index) for\nSydney as publi shed by the Australian Bureau of Statistics. Indexed developer\ncontributions are adopted annually by Council for the financial year.\nNOTE 2: The final indexed contribution identified above remains applicable if paid within the\nsame financial year as the date of determination. If payment is to be made outside\nthis period, you are advised to contact Council prior to payment being made to\ndetermine if CPI increases/decreases have occurred since the date of this consent.\nNOTE 3: A copy of the Wagga Wagga Local Infrastructure Contributions Plan 2019 -2034, is\navailable for inspection at Council Chambers, corner Baylis and Morrow Streets,\nWagga Wagga, or on Council’s website.\nC.80B Prior to the issue of an Occupation Certificate for each stage a compliance certificate under s306 of\nthe Water Management Act 2000 must be obtained in respect of the development relating to water\nmanagement works that may be required in connection with the development. Evidence in writing\nfrom Council must be provided confirming the required contributions have been paid, to the\nsatisfaction of the certifier.\nNOTE1: ‘Water management work’ is defined in s283 of the Water Management Act to mean\na ‘water supply work‘, ‘drainage work‘, ‘sewage work’ or ‘flood work’. These terms\nare defined in that Act.\nNOTE 2: The Council is responsible for issuing compliance certificates and imposing\nrequirements relating to sewerage, drainage and flood works for development in its\narea.\nNOTE 3: Under s306 of the Water Management Act 2000, Council may, as a precondition to\nthe issuing of a compliance certificate, impose a requirement that a payment is made\nor works are carried out, or both, towards the provision of water supply, sewerage,\ndrainage or flood works.\nNOTE 4: The Section 64 Sewer base figure is:\n• $1,769 per one bedroom dwelling in the relevant stage,\n• $2,654 per two bedroom dwelling in the relevant stage,\n• $3,538 per three bedroom or larger dwelling in the relevant stage, and\n• $50,487 for the commercial floor area (payable in Stage 3A/3B only)\nThere is a base credit of $3,538 per dwelling for the four existing dwellings applicable\nin Stage 3C.\nThere is a base credit of $32,039 for the existing commercial space on the site\napplicable in Stage 3A/3B.\nThe Section 64 Sewer contribution (updated by the CPI of 139.7/100.5) required to\nbe paid is:\n• $2,459 per one bedroom dwelling in the relevant stage,\n• $3,689 per two bedroom dwelling in the relevant stage\n• $4,918 per three bedroom dwelling in the relevant stage, and.\n• $70,179 for the commercial floor area (payable in Stage 3A/3B only)\nThe current credit is $4,918 per dwelling for the four existing dwellings applicable in\nStage 3C.\nThe current credit for the existing commercial space on the site is $44,536 applicable\nin Stage 3A/3B.\nNOTE 5: The Section 64 Stormwater base figure is nil.\nNOTE 6: Section 64 contributions shall be indexed in accordance with CPI annually at the\ncommencement of the financial year.\nNOTE 7: The figures outlined in this consent are based on the current rate of CPI. Please be\nadvised that CPI changes on a regular basis and you are advised to contact Council\nprior to payments being made, to ensure no further CPI increases/decreases have\noccurred since the date of this consent.\nGeneral requirements\nC.81 The approved hours of operation for the approved uses of the commercial premises are:\nMonday to Saturday 7:00am to 10:00pm\nSundays and Public Holidays 8:00am to 10:00pm\nDeliveries, waste collection, and loading is approved during the following hours:\nMonday to Saturday 7:00am to 6:00pm\nSundays and Public Holidays 8:00am to 6:00pm\nC.82 Should asbestos material be found, it is to be handled, transported and disposed of in\naccordance with the legislative requirements and standards determined by NSW\nWorkCover. All weighbridge receipts must be provided to Wagga Wagga City Council,\nwithin 14 days of the completion of the demolition/removal.\nNOTE 1: All asbestos material needs to be double wrapped in 200μm thick plastic and\ndisposed of at an EPA licensed facility. In this regard it should be noted that Wagga\nWagga City Council's Gregadoo Waste Facility is the only EPA licensed facility within\nthe Local Government Area to accept asbestos material. Council's Waste\nManagement Supervisor requires 24 hours notice prior to disposal of this material\nNOTE 2: Demolition works involving the removal and disposal of asbestos cement must only\nbe undertaken by contractors who hold a current WorkCover - Demolition Licence\nand a current WorkCover - Class 2 (Restricted) Asbestos Licence.\nNOTE 3: Competent Person (as defined under Safe Removal of Asbestos 2nd Edition\n[NOHSC: 2002 (2005)] means a person possessing adequate qualifications, such as\nsuitable training and sufficient knowledge, experience and skill, for the safe\nperformance of the specific work.\nNOTE 4: A licence may be required for some of the tasks described in the document entitled\nSafe Removal of Asbestos 2nd Edition as requiring a competent person.\nC.83 Consent is granted for the use of the Commercial Premises in Building 3A and 3B for the\nfollowing purposes (as defined by the Wagga Wagga Local Environmental Plan 2010, as\nrelevant):\nOffice, business and retail premises other than premises that are:\n(i) food and drink premises,\n(ii) a funeral chapel,\n(iii) a funeral home,\n(iv) retail premises where firearms within the meaning of the Firearms Act 1996 are sold,\n(v) landscaping material supplies,\n(vi) a market,\n(vii) premises that are a beauty salon or hair dressing salon,\n(viii) premises where a skin penetration procedure within the meaning of the Public Health Act\n2010 is carried out,\n(ix) restricted premises,\n(x) a roadside stall,\n(xi) sex services premises,\n(xii) vehicle sales or hire premises, and\nC.84 All loading, deliveries, and waste collection and management shall occur in accordance\nwith the measures set out in the approved ‘Loading and Operational Waste Management\nPlan’, unless otherwise agreed to, in writing, by the General Manager or delegate.\nC.84A All landscaping and building maintenance on site shall occur in accordance with the\nmeasures set out in the approved ‘Ongoing Landscape and Building Maintenance Plan’ (as\namended from time to time), unless otherwise agreed to, in writing, by the General\nManager or delegate.\nC.85 All internal service roads shall be maintained to the satisfaction of the General Manager or\ndelegate. If directed by the General Manager or delegate, the owner of the land on which\nan internal roads is located shall carry out repairs and maintenance to the satisfaction of\nthe General Manager or delegate.\nC.86 No skip bins associated with Buildings 3A and 3B shall be stored external to the building or\noutside the designated waste rooms.\nC.87 The Flood Emergency Response Plan shall be complied with at all times. If any measures\nto prevent access to the basement become inoperative, all occupants shall be advised, and\nthe measure immediately repaired.\nC.88 Parking allocation within the basement carpark shall be consistent with the plan approved\nunder this consent.\nC.89 The following minimum number of car parking spaces must be made available on site, or\non adjoining land with an appropriate easement, at all times:\nUse Parking Requirement\nShop Top Housing (Residential Apartments) in Building 3A\nand 3B\n142\nGround Floor Commercial Premises in Building 3A and 3B 32\nTownhouses 16\nTotal 190\nThe car parks and all associated facilities must be laid out in accordance with Australian Standards\nAS2890.1.2004, AS2890.2 2018 and AS/NZS2890.6.2022.\nC.90 Illumination of the car park must be in accordance with AS 1158.3.1.2020, as amended,\nlighting for roads and public spaces.\nC.91 Provision shall be made for the parking of bicycles on site in accordance with AS 2890.3-\n2015 “Bicycle parking facilities” is required.\nC.92 Wagga Wagga City Councils Engineering Guidelines for Subdivisions and Development\nshall be referred to for the design of engineering requirements. Any aspect of the design\nwhich is not covered in Councils document should reference relevant specifications\nselected from other sources. Any aspect of the design that is not in accordance or not\ncovered in council's document shall be listed and submitted with the plans for separate\napproval.\nD. SCHEDULE D - Activity Approval Conditions (Section 68)\nN/A\nE. SCHEDULE E - Prescribed Conditions\nConditions under this schedule are prescribed conditions for the purposes of section 4.17 (11) of\nthe Environmental Planning and assessment Act 1979.\nE.1 Compliance with Building Code of Australia and insurance requirements under the Home\nBuilding Act 1989 (clause 69 EP&A Reg 2021)\n(1) It is a condition of a development consent for development that involves building work that\nthe work must be carried out in accordance with the requirements of the Building Code of\nAustralia.\n(2) It is a condition of a development consent for development that involves residential\nbuilding work for which a contract of insurance is required under the Home Building Act\n1989, Part 6 that a contract of insurance is in force before building work authorised to be\ncarried out by the consent commences.\n(3) It is a condition of a development consent for a temporary structure used as an\nentertainment venue that the temporary structure must comply with the Building Code of\nAustralia, Volume 1, Part B1 and NSW Part I5.\n(4) In subsection (1), a reference to the Building Code of Australia is a reference to the Building\nCode of Australia as in force on the relevant date.\n(5) In subsection (3), a reference to the Building Code of Australia is a reference to the Building\nCode of Australia as in force on the day on which the application for development consent\nwas made.\n(6) This section does not apply-\n(a) to the extent to which an exemption from a provision of the Building Code of Australia\nor a fire safety standard is in force under the Environmental Planning and Assessment\n(Development Certification and Fire Safety) Regulation 2021, or\n(b) to the erection of a temporary building, other than a temporary structure to which\nsubsection (3) applies.\n(7) In this section -\nrelevant date has the same meaning as in the Environmental Planning and Assessment\n(Development Certification and Fire Safety) Regulation 2021, section 19.\nE.2 Erection of signs (clause 70 EP&A Reg 2021)\n(1) This section applies to a development consent for development involving building work,\nsubdivision work or demolition work.\n(2) It is a condition of the development consent that a sign must be erected in a prominent\nposition on a site on which building work, subdivision work or demolition work is being\ncarried out-\n(a) showing the name, address and telephone number of the principal certifier for the\nwork, and\n(b) showing the name of the principal contractor, if any, for the building work and a\ntelephone number on which the principal contractor may be contacted outside\nworking hours, and\n(c) stating that unauthorised entry to the work site is prohibited.\n(3) The sign must be-\n(a) maintained while the building work, subdivision work or demolition work is being\ncarried out, and\n(b) removed when the work has been completed.\n(4) This section does not apply in relation to-\n(a) building work, subdivision work or demolition work carried out inside an existing\nbuilding, if the work does not affect the external walls of the building, or\n(b) Crown building work certified to comply with the Building Code of Australia under the\nAct, Part 6.\nE.3 Notification of Home Building Act 1989 requirements (clause 71 EP&A Reg 2021)\n(1) This section applies to a development consent for development involving residential\nbuilding work if the principal certifier is not the council.\n(2) It is a condition of the development consent that residential building work must not be\ncarried out unless the principal certifier for the development to which the work relates has\ngiven the council written notice of the following-\n(a) for work that requires a principal contractor to be appointed-\ni. the name and licence number of the principal contractor, and\nii. the name of the insurer of the work under the Home Building Act 1989, Part 6,\n(b) for work to be carried out by an owner-builder-\ni. the name of the owner-builder, and\nii. if the owner-builder is required to hold an owner-builder permit under the\nHome Building Act 1989-the number of the owner-builder permit.\n(3) If the information notified under subsection (2) is no longer correct, it is a condition of the\ndevelopment consent that further work must not be carried out unless the principal\ncertifier has given the council written notice of the updated information.\n(4) This section does not apply in relation to Crown building work certified to comply with the\nBuilding Code of Australia under the Act, Part 6.\nE.4 Shoring and adequacy of adjoining property (clause 74 EP&A Reg 2021)\n(1) This section applies to a development consent for development that involves excavation\nthat extends below the level of the base of the footings of a building, structure or work on\nadjoining land, including a structure or work in a road or rail corridor.\n(2) It is a condition of the development consent that the person having the benefit of the\ndevelopment consent must, at the person’s own expense-\n(a) protect and support the building, structure or work on adjoining land from possible\ndamage from the excavation, and\n(b) if necessary, underpin the building, structure or work on adjoining land to prevent\ndamage from the excavation.\n(3) This section does not apply if-\n(a) the person having the benefit of the development consent owns the adjoining land, or\n(b) the owner of the adjoining land gives written consent to the condition not applying.\nE.5 Fulfilment of BASIX commitments (clause 75 EP&A Reg 2021)\nIt is a condition of a development consent for the following that each commitment listed in a\nrelevant BASIX certificate is fulfilled-\n(a) BASIX development,\n(b) BASIX optional development, if the development application was accompanied by a BASIX\ncertificate.\nF. SCHEDULE F - General Terms of Approval (Integrated Development)\nN/A","stage":"general","stage_basis":"heading","page":5}]});
